    Ignores all other characters.
    """
    bracket_pairs = {')': '(', ']': '[', '}': '{'}
    opening_brackets = set(bracket_pairs.values())
    stack = []

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in bracket_pairs:
            if not stack or stack.pop() != bracket_pairs[char]:
                return False

    return not stack


if __name__ == "__main__":
    test_cases = {
        "([]{})": True,
        "([)]": False,
        "((({[]})))": True,
        "[({})](]": False,
        "abc(def[ghi]{jkl})": True,
        "abc(def[ghi]{jkl}": False,
        "": True,
        "no brackets here": True,
        "([{}])(){}[]": True,
        "([{}])({[)]}": False,
    }

    for test_str, expected in test_cases.items():
        result = are_brackets_balanced(test_str)
        print(f"Input: {test_str!r} -> Balanced: {result} (Expected: {expected})")

def is_balanced(s, pairs):
    """
    Check if the string s has balanced brackets according to the custom pairs.

    Args:
        s (str): The input string containing brackets and other characters.
        pairs (list of tuple): List of tuples where each tuple is (opening, closing) bracket.

    Returns:
        bool: True if balanced, False otherwise.
    """
    opening_brackets = {opening for opening, _ in pairs}
    closing_brackets = {closing for _, closing in pairs}
    bracket_map = {closing: opening for opening, closing in pairs}

    stack = []

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack[-1] != bracket_map[char]:
                return False
            stack.pop()

    return not stack


if __name__ == "__main__":
    test_cases = [
        ("[{()}]", [('(', ')'), ('[', ']'), ('{', '}')], True),
        ("[{(])}", [('(', ')'), ('[', ']'), ('{', '}')], False),
        ("", [('(', ')')], True),
        ("abc", [('(', ')')], True),
        ("([{}])", [('(', ')'), ('[', ']'), ('{', '}')], True),
        ("([}{])", [('(', ')'), ('[', ']'), ('{', '}')], False),
        ("<({[]})>", [('<', '>'), ('(', ')'), ('[', ']'), ('{', '}')], True),
        ("<({[)]}>", [('<', '>'), ('(', ')'), ('[', ']'), ('{', '}')], False),
    ]

    for i, (string, pairs, expected) in enumerate(test_cases, 1):
        result = is_balanced(string, pairs)
        print(f"Test case {i}: {'Passed' if result == expected else 'Failed'}")

def longest_palindromic_substring(s: str) -> str:
    """
    Finds the longest palindromic substring in the input string.
    If multiple substrings have the same maximum length, returns the first one.
    """
    if not s:
        return ""

    start, max_length = 0, 1

    def expand_around_center(left: int, right: int) -> (int, int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1

    for i in range(len(s)):
        left1, length1 = expand_around_center(i, i)
        left2, length2 = expand_around_center(i, i + 1)

        if length1 > max_length:
            start, max_length = left1, length1
        if length2 > max_length:
            start, max_length = left2, length2

    return s[start:start + max_length]


